     \]
     \[
     \frac{10 \sqrt{3}}{1} = \frac{10}{\sin(120^\circ)} = \frac{PR}{\sin(120^\circ)}
     \]
     \[
     10 \sqrt{3} = 10 \cdot \frac{\sqrt{3}}{2} = \frac{10 \sqrt{3}}{2} = \frac{PR}{\sin(120^\circ)}
     \]
     \[
     PR = 10 \sqrt{3}
     \]

