# Define the sum of two dice
def sum_of_dice():
    return sp.symbols('sum_of_dice')

# Define the sum of the numbers on the faces of the dice
def sum_of_faces():
    return sp.symbols('sum_of_faces')

# Define the sum of the dice as a function of the sum of the faces
def sum_of_dice_as_a_function_of_sum_of_faces():
    return sum_of_faces() + sum_of_faces()

# Define the sum of the faces as a function of the sum of the dice
def sum_of_faces_as_a_function_of_sum_of_dice():
